sys_script_include.script:
var RaaSUtils = Class.create();
RaaSUtils.prototype = {
    initialize: function() {
    },
	refQualMedia: function(){
		var mediasNotToBeShown = [];

		var grReview = new GlideRecord("x_1593179_raas_review");
		grReview.addEncodedQuery("state!=4^opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe");
		grReview.query();
		while(grReview.next()){
			mediasNotToBeShown.push(grReview.media.sys_id.toString());
		}

		var moviesToBeShown = [];
		var grMedias = new GlideRecord("x_1593179_raas_media");
		grMedias.addQuery("state", "3");
		grMedias.query();
		while(grMedias.next()){
			if(mediasNotToBeShown.indexOf(grMedias.getUniqueValue()) == -1){
				moviesToBeShown.push(grMedias.getUniqueValue());
			}
		}

		return "sys_idIN" + moviesToBeShown.join(",");

	},
    type: 'RaaSUtils'
};
